176	   * @param {HTMLElement}       resultsEl - The #orch-preflight-results container
177	   *                                        (passed as parameter; not captured from closure).
178	   */
179	  function _handleStartRun(startBtn, planInput, resultsEl) {
180	    var planPath = planInput.value.trim();
181	    if (!planPath || !allChecksPassed) return;
182	
183	    startBtn.disabled = true;
184	    startBtn.textContent = 'Starting…';
185	
186	    API.orchestratorStart(planPath, false).then(function (result) {
187	      if (result && result.started) {
188	        var runStatusFilename = result.runStatusFilename || null;
189	        planInput.value = '';
190	        resultsEl.innerHTML =
191	          '<p class="success-banner">✓ Orchestrator launched' +
192	          (result.pid ? ' (PID\u00a0' + result.pid + ')' : '') +
193	          '. Waiting for the run to appear in the queue below…</p>';
194	        allChecksPassed = false;
195	        startBtn.disabled = true;
196	        refreshQueue();
197	
198	        // Poll the run-status tombstone so we can surface fatal early
199	        // failures (e.g. invalid API key) that complete before the first
200	        // queue poll cycle.
201	        if (runStatusFilename) {
202	          var pollCount = 0;
203	          var MAX_STATUS_POLLS = 15; // 2s × 15 = 30s window
204	          var statusPollTimer = setInterval(function () {
205	            pollCount++;
206	            API.orchestratorGetRunStatus(runStatusFilename).then(function (status) {
207	              if (!status) return; // file not yet written — run still in progress
208	              clearInterval(statusPollTimer);
209	              if (status.result === 'ERROR' && status.error) {
210	                resultsEl.innerHTML =
211	                  '<p class="error-banner">Run failed: ' +
212	                  escapeHtml(status.error) + '</p>';
213	              }
214	              // SUCCESS: queue will reflect the project; leave the banner.
215	            }).catch(function () {
216	              // Transient error — keep polling.
217	            });
218	            if (pollCount >= MAX_STATUS_POLLS) {
219	              clearInterval(statusPollTimer);
220	            }
221	          }, 2000);
222	          _orchStatusPollCleanups.push(function () { clearInterval(statusPollTimer); });
223	        }
224	      } else {
225	        // Checks re-evaluated by server — update the checklist.
226	        renderPreflightResults((result && result.checks) ? result.checks : []);
227	      }
228	    }).catch(function (err) {
229	      window.alert('Failed to start: ' + ((err && err.message) ? err.message : String(err)));
230	      startBtn.disabled = !allChecksPassed;
231	      startBtn.textContent = 'Start Run';
232	    }).then(function () {
233	      startBtn.textContent = 'Start Run';
234	    });
235	  }
