351	        cell.appendChild(OrchestratorWidgets.renderDismissButton(id, function () {
352	          delete expandedIds[id];
353	          refreshQueue();
354	        }));
355	      } else if (entry.projectExists === true && entry.expectedRepo && entry.expectedSlug) {
356	        var link = document.createElement('a');
357	        link.href = '#/projects/' +
358	          encodeURIComponent(entry.expectedRepo) + '/' +
359	          encodeURIComponent(entry.expectedSlug);
360	        link.className = 'btn btn-sm btn-secondary orch-queue-action-btn';
361	        link.textContent = 'View Project';
362	        cell.appendChild(link);
363	      } else if (entry.projectExists === true && entry.expectedSlug && !entry.expectedRepo) {
364	        // Legacy queue entry without expectedRepo — omit the project link to
365	        // avoid constructing a broken bare-slug URL. The entry is still shown
366	        // in the queue but no navigation link is rendered.
367	      }
368	    });
369	
370	    var toggleBtns = container.querySelectorAll('.orch-row-toggle');
371	    Array.prototype.forEach.call(toggleBtns, function (btn) {
372	      btn.addEventListener('click', function () {
373	        var id = btn.getAttribute('data-entry-id');
374	        if (id) expandedIds[id] = !expandedIds[id];
