388	   *                                 so it is cancelled when renderOrchestrator() or
389	   *                                 refreshQueue() next runs.
390	   *
391	   *  Note: _orchStatusPollCleanups is a separate registry for status-poll timers
392	   *  and is intentionally excluded from this function's scope. Status-poll cleanups
393	   *  are only drained by renderOrchestrator() (full view re-render), never by
394	   *  refreshQueue() or _mountLogPreviews(). */
395	  function _mountLogPreviews(container, entries) {
396	    entries.forEach(function (entry) {
397	      var id = entry.id || '';
398	      if (!expandedIds[id] || !entry.logFilename || !entry.expectedRepo || !entry.expectedSlug) return;
399	      var previewEl = document.getElementById('orch-log-' + id);
400	      if (!previewEl) return;
401	      var cleanup = OrchestratorWidgets.renderLogPreview(
402	        previewEl,
403	        entry.expectedRepo,
404	        entry.expectedSlug,
405	        entry.logFilename
406	      );
407	      _orchLogPreviewCleanups.push(cleanup);
408	    });
409	  }
