413	  function renderQueueTable(container, entries) {
414	    // Save viewport scroll position before replacing innerHTML — the document
415	    // viewport is the scrolling context (not the container, which has no
416	    // overflow CSS), so window.scrollY is the correct save/restore target.
417	    var savedScrollY = window.scrollY;
418	
419	    if (!entries.length) {
420	      container.innerHTML = '<p class="text-muted orch-empty-queue">No active runs in the queue.</p>';
421	      return;
422	    }
423	
424	    _clearSuccessBanner();
425	    container.innerHTML = _buildQueueHtml(entries);
426	    _bindQueueActions(container, entries);
427	    _mountLogPreviews(container, entries);
428	
429	    // Restore scroll position after all DOM manipulation is complete.
430	    // Must be the last statement so intermediate DOM mutations do not
431	    // interfere with the restored position.
432	    window.scrollTo(0, savedScrollY);
433	  }
434	
435	  // 8. Kick off the first queue fetch and register the polling interval.
436	  refreshQueue();
437	  Router._setPolling(refreshQueue, 5000);
438	}
