457	/** Formats elapsed time from an ISO start timestamp. */
458	function _orchElapsed(startedAt) {
459	  if (!startedAt) return '—';
460	  try {
461	    var diff = Date.now() - new Date(startedAt).getTime();
462	    if (isNaN(diff) || diff < 0) return '—';
463	    var secs = Math.round(diff / 1000);
464	    if (secs < 60)  return secs + 's';
465	    var mins = Math.floor(secs / 60);
466	    if (mins < 60)  return mins + 'm ' + (secs % 60) + 's';
467	    return Math.floor(mins / 60) + 'h ' + (mins % 60) + 'm';
468	  } catch (_) {
469	    return '—';
470	  }
471	}

