157	/**
158	 * Flush pending microtask queues so that chained Promise callbacks resolve
159	 * before assertions run.
160	 *
161	 * The loop runs 10 times because the async paths under test involve multiple
162	 * hops — e.g. orchestratorGetQueue resolves → renderQueueTable is called →
163	 * DOM mutations fire — each of which queues a fresh microtask tick.  One or
164	 * two iterations are not sufficient to drain these chains; 10 was chosen
165	 * empirically to cover all current paths with a comfortable margin.  If a
166	 * future test introduces a longer chain, increase this count accordingly.
167	 */
168	async function flushPromises(): Promise<void> {
169	  for (let i = 0; i < 10; i++) await Promise.resolve();
170	}
